function compute(inputs) {
  const M = inputs.M;
  const d = inputs.d;
  const N = 4;
  // Compute out-degree L(j) = sum of row j
  const L = M.map(row => row.reduce((a, b) => a + b, 0));
  // Initialize ranks uniformly
  let r = new Array(N).fill(1 / N);
  const maxIter = 100;
  const tol = 1e-10;
  let iter = 0;
  let converged = false;
  let r_prev = r.slice();
  while (iter < maxIter && !converged) {
    r_prev = r.slice();
    const newR = new Array(N).fill(0);
    for (let i = 0; i < N; i++) {
      let sum = 0;
      for (let j = 0; j < N; j++) {
        if (M[j][i] === 1 && L[j] > 0) {
          sum += r_prev[j] / L[j];
        }
      }
      newR[i] = (1 - d) / N + d * sum;
    }
    r = newR;
    // Check convergence
    let diff = 0;
    for (let i = 0; i < N; i++) {
      diff += Math.abs(r[i] - r_prev[i]);
    }
    if (diff < tol) converged = true;
    iter++;
  }
  // Normalize to ensure sum exactly 1 (avoid floating point drift)
  const sumR = r.reduce((a, b) => a + b, 0);
  r = r.map(val => val / sumR);
  // Prepare table: per page i: r_i, L(i), incoming sum
  const tableRows = [];
  for (let i = 0; i < N; i++) {
    let incomingSum = 0;
    for (let j = 0; j < N; j++) {
      if (M[j][i] === 1 && L[j] > 0) {
        incomingSum += r[j] / L[j];
      }
    }
    tableRows.push([
      String.fromCharCode(65 + i),
      r[i].toFixed(6),
      L[i],
      incomingSum.toFixed(6)
    ]);
  }
  const table = {
    columns: ["Page", "r_i", "L(i)", "Incoming sum"],
    rows: tableRows
  };
  // Insight
  const maxR = Math.max(...r);
  const minR = Math.min(...r);
  let insight = `Max rank = ${maxR.toFixed(4)} (page ${String.fromCharCode(65 + r.indexOf(maxR))}), min rank = ${minR.toFixed(4)} (page ${String.fromCharCode(65 + r.indexOf(minR))}). `;
  if (d === 0) {
    insight += "With d=0, all pages have equal rank 0.25.";
  } else {
    insight += `With d=${d.toFixed(2)}, pages with more incoming links tend to have higher rank.`;
  }
  return {
    r: r,
    table: table,
    insight: insight
  };
}
